            <div className={`absolute top-1.5 bottom-1.5 w-[140px] bg-white dark:bg-blue-600 rounded-full shadow-md transition-all duration-300 ease-[cubic-bezier(0.25,0.1,0.25,1.0)] ${activeOrg === "OSIS" ? "left-1.5" : "left-[148px]"}`} />

